manufacturer = value['Manufacturer'].iloc[0].upper() if 'Manufacturer' in value.columns else ''
scanning_seq = value['ScanningSequence'].iloc[0] if 'ScanningSequence' in value.columns else ''

if 'GE' in manufacturer:
    if 'SE' not in scanning_seq:
        raise ValidationError(f"GE DWI should use SE-EPI sequence. Found: {scanning_seq}")
elif 'SIEMENS' in manufacturer:
    if 'EP' not in scanning_seq:
        raise ValidationError(f"Siemens DWI should use EP (ep2d_diff) sequence. Found: {scanning_seq}")
elif 'PHILIPS' in manufacturer:
    if 'EP' not in scanning_seq and 'SE' not in scanning_seq:
        raise ValidationError(f"Philips DWI should use EP/SE (Zoom Diffusion) sequence. Found: {scanning_seq}")
